from arrow.formatter import Formatter
f = Formatter()

# Check what methods/format strings it uses for months
for attr in dir(f):
    if not attr.startswith('_'):
        val = getattr(f, attr)
        if callable(val):
            continue
        if isinstance(val, str):
            print(f"{attr}: {repr(val)}")
